const SCA_CASES={

/* ===================== 1. Febrile child ===================== */
"u19-fever":{g:1,title:"Feverish toddler: parent wants antibiotics",mode:"phone",pt:"Chloe",voice:"f",who:"Chloe Bennett, mother of Leo (20 months)",
 teach:{why:"Phone assessment of an unwell child is one of the commonest SCA tasks. You can't examine, so the marks are in a structured history, a clear decision about who needs seeing, and a specific safety-net.",
  twist:"Mum wants antibiotics so Leo can go back to nursery and she can go to work. Underneath, a neighbour's child had meningitis last year.",
  ice:["Ideas: 'It's probably a chest infection: he needs antibiotics.'","Concerns: meningitis (neighbour's child); missing work.","Expectations: antibiotics today; a note for nursery."],
  gather:["Duration and height of fever; response to paracetamol or ibuprofen","Activity: 'Is he playing between doses? Smiling? Waking normally?'","Feeding, drinking and wet nappies (aim: 4 or more a day)","Breathing: fast, noisy, sucking in under the ribs, grunting","Colour: pale, mottled, blue","Rash: does it fade under a glass?","Vomiting, diarrhoea, seizures, ear pulling, limb or joint problems","Immunisations, past history, other children unwell, nursery bugs"],
  flags:["RED (urgent face-to-face, or 999 if life-threatening): pale, mottled or blue; doesn't respond or can't be roused; weak, high-pitched or continuous cry; grunting or breathing over 60 a minute; non-blanching rash; bulging fontanelle; neck stiffness; seizure; age under 3 months with 38°C or more","AMBER (see face to face): not responding normally or not smiling; reduced activity; nasal flaring or fast breathing; dry mouth, poor feeding, fewer wet nappies; age 3–6 months with 39°C or more; fever 5 days or more; rigors; limb swelling or not weight-bearing","GREEN: normal colour, responds normally, content or smiling, stays awake, strong cry, moist mouth"],
  manage:["Use the NICE traffic light system by history (NICE NG143)","All green: care at home with advice; no antibiotics for a viral illness","Any amber, a worried parent, or you can't assess properly: see face to face today","Paracetamol OR ibuprofen only if the child is distressed, not just to lower the number; don't give both at once (alternate only if distress returns before the next dose is due)","Regular fluids, don't over- or under-dress, no tepid sponging","Nursery: children with a high temperature should stay at home until it settles (UKHSA)"],
  phrases:["'You know Leo best. What's worrying you most today?'","'I can hear how worried you are about meningitis, and that makes sense after what happened next door. Let me ask the questions that tell us about that.'","'Antibiotics don't help viruses, and they won't bring the temperature down any faster, but here's what will help him.'","'Would you like me to see him this afternoon so we can look at his ears and chest together?'"],
  safety:"Call 999 for: a rash that doesn't fade under a glass, he's floppy or hard to wake, he's struggling to breathe or grunting, or a fit. Call us back today or 111 if: he stops drinking or has fewer than 3–4 wet nappies, he's less responsive, the fever lasts 5 days, or you're worried. Written advice too.",
  pitfalls:{dg:["Not asking about activity and wet nappies","Forgetting the glass test","Missing the meningitis concern"],cm:["Prescribing antibiotics to satisfy the request","Vague safety-net ('call if worse')","Not offering a face-to-face check when the parent is very worried"],rto:["Dismissing the neighbour's story","Lecturing about antibiotic resistance","Ignoring the work and nursery pressure"]},
  src:"NICE NG143 Fever in under 5s (2019, updated 2021) · NICE CKS Feverish children · UKHSA guidance on children with a high temperature attending childcare"},
 model:[["dr","Hello, it's Dr Pinaware from the surgery. Am I speaking to Leo's mum? Can I check Leo's date of birth, and that it's a good time to talk?"],["pt","Yes, it's Chloe. He was born on the fifth of March last year. It's fine, he's on my lap."],["dr","Thanks, Chloe. Tell me what's been happening with Leo."],["pt","He's had a temperature for two days, up to nearly 39, and a runny nose and cough. I think he needs antibiotics. Nursery won't take him."],["dr","That sounds a tough couple of days. Before we decide anything, can I ask some questions so I get a proper picture? When the paracetamol's working, how is he: is he playing, smiling at you?"],["pt","Yeah, he's pottering about with his cars when it kicks in. Grumpy when it wears off."],["dr","That's really reassuring. Is he drinking, and how many wet nappies today?"],["pt","Drinking, not eating much. Four or five wet nappies."],["dr","Good. Any breathing that looks fast or hard work, any rash, or any time he's been floppy or hard to wake?"],["pt","No rash. His breathing's fine. He's not floppy. It's just… my neighbour's little girl had meningitis last year."],["dr","Thank you for telling me. That must be frightening to have in your mind. The things that would worry me about meningitis are a rash that doesn't fade with a glass, being very drowsy or floppy, a stiff neck or a fit. From what you're telling me, Leo doesn't have any of those."],["pt","OK. So do I need antibiotics?"],["dr","What it sounds like is a viral cold with a temperature. Antibiotics don't work on viruses and won't bring his temperature down any quicker. What helps is fluids, and paracetamol or ibuprofen if he's miserable. Would you like me to see him this afternoon to check his ears and chest, so you feel sure?"],["pt","Yes please, that would put my mind at rest."],["dr","Let's do that at 3. And if before then he has a rash that doesn't fade under a glass, is floppy or hard to wake, struggles to breathe or has a fit, call 999. If he stops drinking or has fewer wet nappies, call us straight away. Can you tell me back what you'll watch for?"],["pt","Rash that doesn't fade, floppy, breathing, a fit: 999. Not drinking: call you. And we'll see you at 3."],["dr","Perfect. On nursery: they're right that he should stay home until his temperature's gone. I can give you a work note if that helps."]],
 live:{opening:"Hi, it's about my little boy, Leo. He's had a temperature for two days and I think he needs antibiotics.",
  notes:[["Patient","Leo Bennett, 20 months"],["Caller","Chloe Bennett (mother)"],["Consultation","Telephone, booked as 'urgent: child temp'"],["Past history","Born at term; immunisations up to date"],["Medicines","None regular; Calpol at home"],["Last contact","Seen at 12 months for a cold"]],
  brief:`You are a trained SCA role-player. You play CHLOE BENNETT, 29, mother of LEO, 20 months old, on a PHONE call with the GP. You work as a care assistant on early shifts. Plain, friendly British English, a bit rushed and anxious. 1–3 sentences per reply. No medical jargon.
FACTS (give when asked; don't volunteer everything): Fever 2 days, highest 38.9 at night; runny nose and cough; eating less but drinking milk and water; 4–5 wet nappies today; playing with his cars when Calpol is working, grumpy when it wears off; wakes normally; no rash (if asked about the glass test you haven't done it but can check: "No, it goes away under the glass"); breathing normal, no grunting or sucking in; no vomiting or diarrhoea; no fits; not pulling ears much; immunisations up to date; older cousin had a cold last week.
HIDDEN: Concern: your neighbour's daughter had meningitis last year and was in intensive care. Reveal only if asked what's worrying you, or if the doctor is warm and gives you space. Expectation: antibiotics so nursery takes him tomorrow and you can work your shift (you'll lose pay). Share if asked what you were hoping for.
REACTIONS: If the doctor asks about meningitis signs and explains clearly, you relax. If refused antibiotics without explanation, become frustrated ("So I just have to watch him?"). If offered a face-to-face check today you're grateful. Accept no antibiotics if the reasons are clear and you feel listened to. If the doctor gives a specific safety-net, you can repeat it back. Stay in character.`,
  dg:{activity:"Activity, smiling, waking",fluids_nappies:"Drinking and wet nappies",breathing:"Breathing signs",rash_glass:"Rash and the glass test",other_symptoms:"Other symptoms (vomiting, fits, ears)",background:"Immunisations and background",psychosocial:"Work and nursery impact"},
  cm:{traffic_light:"Clear decision by traffic light",no_antibiotics:"Explained no antibiotics",antipyretic_advice:"Correct paracetamol or ibuprofen advice",fluids_advice:"Fluids and care at home",offer_f2f:"Offered a face-to-face check",nursery_note:"Addressed nursery and work"},
  bad:{prescribed_abx:"Prescribed antibiotics",dismissive:"Dismissed the worry",jargon:"Jargon",vague_safety_net:"Vague safety-net"},
  clues:{meningitis_fear:"Concern: neighbour's child had meningitis",wants_abx:"Expectation: antibiotics for nursery",work_pressure:"Needs to work her shift",playing:"Playing between doses",nappies:"4–5 wet nappies",no_rash:"No rash; fades under glass",breathing_ok:"Breathing normal"},
  hints:{activity:"How is he between doses of paracetamol?",fluids_nappies:"Drinking and wet nappies?",breathing:"Any signs of breathing difficulty?",rash_glass:"Rash? Does it fade under a glass?",concerns:"Is something specific worrying her?",offer_f2f:"Would seeing him today help?",nursery_note:"What about nursery and her work?",safety_net:"999 signs vs call back, with timescales."},
  hyp:"e.g. Viral URTI? Otitis media? Any amber or red features? Why antibiotics?",
  exam:`CASE: Phone call with Chloe, mother of Leo (20 months), fever 2 days with coryza and cough. Green features only by history (playing between doses, 4–5 wet nappies, normal breathing, no rash). Hidden: fear of meningitis (neighbour's child); wants antibiotics so nursery takes him and she can work.
WHAT EARNS MARKS:
Data gathering: structured traffic-light history (activity, colour, breathing, hydration and nappies, rash with glass test, drowsiness, fits); age and duration; immunisations; elicits meningitis fear and the work/nursery pressure.
Clinical management (weighted more): clear decision that he's green by history; no antibiotics with clear reasons; correct antipyretic advice (only if distressed, not both at once); fluids; offers face-to-face review today given parental concern or inability to examine; specific safety-net (999 signs: non-blanching rash, floppy or unrousable, breathing difficulty, seizure; call back for poor intake, fewer nappies, fever 5 days); nursery advice (stay home until temperature settled) and work note.
Relating to others: warm phone manner, identity check, acknowledges the meningitis fear, shared decision on review, plain language, checks understanding.
Common errors: prescribing antibiotics; missing wet nappies or glass test; vague safety-net; lecturing about resistance; ignoring work worries.`}},

/* ===================== 2. Teen contraception ===================== */
"u19-contraception":{g:1,title:"15-year-old asking for the pill on her own",mode:"video",pt:"Mia",voice:"f",who:"Mia Clarke, 15",
 teach:{why:"Tests Fraser and Gillick competence, confidentiality and its limits, and safeguarding, all while staying non-judgemental. There is often a hidden clinical urgency, such as emergency contraception.",
  twist:"She had unprotected sex 3 days ago and doesn't realise emergency contraception still matters. Her mum checks her phone.",
  ice:["Ideas: 'My friend's on the pill and it's fine.'","Concerns: mum finding out; being pregnant.","Expectations: a prescription for the pill today, kept secret."],
  gather:["Confirm she's alone and can talk privately (video)","Relationship: partner's age, how they met, does she feel able to say no?","Sexual history: last unprotected sex (date and time), contraception used, STI symptoms","Exploitation screen: older partner, gifts, alcohol or drugs, missing school, being asked to keep it secret, pressure","Medical: migraine with aura, BP, BMI, smoking, VTE family history, medicines","Mental health, school, home, who she can talk to"],
  flags:["Under 13: sexual activity is always a child protection referral","13–15: assess exploitation risk; refer if concerns (big age gap, coercion, gifts, substances, missing school, secrecy)","Unprotected sex within 5 days: emergency contraception now"],
  manage:["Assess Fraser criteria: understands advice; can't be persuaded to tell parents (or let you tell them); likely to have sex anyway; health likely to suffer without contraception; it's in her best interests","Emergency contraception: copper IUD is most effective (within 5 days); otherwise levonorgestrel within 72 hours or ulipristal within 120 hours. Pregnancy test in 3 weeks","Ongoing contraception: explain LARC (implant most effective) as well as the pill; condoms for STIs","STI testing: chlamydia and gonorrhoea, offer HIV and syphilis","Confidentiality: private unless she or someone else is at serious risk of harm, and you'd tell her first","Encourage, but don't require, involving a trusted adult"],
  phrases:["'What you tell me stays between us, unless I'm worried you or someone else is at serious risk of harm. If that happened, I'd talk to you first.'","'Some people your age are with someone older. Can I ask how old your boyfriend is?'","'When was the last time you had sex without a condom?'","'There's a really effective option called the implant. Would you like to hear about it alongside the pill?'"],
  safety:"Pregnancy test in 3 weeks or if the period is late or unusual; seek help for heavy bleeding, pelvic pain or symptoms of infection; who to contact if she ever feels pressured or unsafe; follow-up in 3 months for the pill (BP and side effects).",
  pitfalls:{dg:["Not asking about recent unprotected sex","Not asking the partner's age","Skipping UKMEC checks (migraine with aura)"],cm:["Missing emergency contraception","Not offering LARC or STI testing","Refusing because she's under 16"],rto:["Judgemental tone","Insisting on telling her mum","Promising total confidentiality"]},
  src:"GMC 0–18 years guidance · Fraser guidelines and Gillick competence · FSRH Emergency contraception (2017, amended) · FSRH UKMEC 2016 · Brook and BASHH 'Spotting the signs' proforma"},
 model:[["dr","Hi, I'm Dr Pinaware. Can I check your name and date of birth? And are you somewhere private where no one can overhear?"],["pt","Mia Clarke, second of June 2011. Yeah, I'm in my bedroom. Mum's at work."],["dr","Thanks, Mia. What can I help you with today?"],["pt","I want to go on the pill. My friend's on it. But I don't want my mum to know."],["dr","Thanks for coming to talk to me about it: that's a sensible thing to do. Before we go on, I want you to know what you tell me stays between us, unless I'm worried you or someone else is at serious risk of harm, and if that happened I'd talk to you first. Is that OK?"],["pt","OK."],["dr","Are you seeing someone at the moment? Can I ask how old he is and how you met?"],["pt","Jordan. He's 17. He's at college with my cousin. We've been together four months."],["dr","Do you feel you can say no to anything you don't want to do, and has anyone asked you to keep the relationship secret or given you things like alcohol or presents?"],["pt","No, nothing like that. He's nice. My mum just wouldn't get it."],["dr","Thanks for being so open. When was the last time you had sex without a condom?"],["pt","Um… Saturday. The condom split."],["dr","Thank you for telling me: that's really important. Saturday is 3 days ago, so emergency contraception still works. The most effective is a copper coil, which can go in up to 5 days after, or there's a tablet you can take today. Shall I explain both so you can choose?"],["pt","The tablet. I don't want a coil."],["dr","That's fine. I'll arrange that now, and I'd suggest a pregnancy test in 3 weeks. For the future, there's the pill, and there's also the implant in your arm, which works for 3 years and you don't have to remember anything. Do you get headaches with flashing lights?"],["pt","No. The implant sounds better, actually."],["dr","Let's book that with our nurse. Condoms are still important for infections, and I'd like to offer you a simple test for chlamydia and gonorrhoea. Is there an adult you trust you could talk to about this, if you ever wanted to?"],["pt","My auntie, maybe."],["dr","That's great. Can you tell me back what we've planned today?"]],
 live:{opening:"Hi. Um, I wanted to go on the pill, but I don't want my mum to know.",
  notes:[["Patient","Mia Clarke, 15"],["Consultation","Video call, booked online by the patient"],["Past history","Asthma (mild), salbutamol PRN"],["Allergies","None"],["Last seen","Age 13, asthma review"],["Social","Lives with mum and younger brother"]],
  brief:`You are a trained SCA role-player. You play MIA CLARKE, 15, on a VIDEO call from your bedroom, alone (mum is at work). Shy at first, warms up if the doctor is kind and non-judgemental. Short teenage answers, 1–2 sentences. No jargon.
FACTS (give when asked): Boyfriend Jordan, 17, at college with your cousin, together 4 months, you feel safe, he doesn't pressure you, no gifts, alcohol or drugs, no one asked you to keep it secret apart from you not wanting mum to know. You're at school, doing OK. Periods regular, last period 2 weeks ago. Had sex Saturday (3 days ago) and the condom split: reveal ONLY if the doctor asks about recent sex without a condom or about the last time you had sex. You don't know emergency contraception still works. No headaches with flashing lights; don't smoke; no clotting in family; mild asthma. No STI symptoms.
HIDDEN: Concern: mum finding out (she checks your phone sometimes) and secretly scared you might be pregnant. Reveal the pregnancy worry if asked what's worrying you. Expectation: the pill today and no one told.
REACTIONS: If the doctor says they must tell your mum, become upset and quiet ("Forget it then"). If confidentiality and its limits are explained kindly, relax. If offered emergency contraception, prefer the tablet over the coil unless the doctor explains the coil well, then say you'll think about it. Interested in the implant if explained. Agree to a chlamydia test if offered simply. Your auntie is a trusted adult if asked. Stay in character.`,
  dg:{privacy_check:"Checked she's alone and private",partner_age:"Partner's age and relationship",exploitation_screen:"Screened for pressure or exploitation",last_upsi:"Asked about recent unprotected sex",ukmec_checks:"Migraine, smoking, clot history",school_home:"School, home, support"},
  cm:{confidentiality_limits:"Explained confidentiality and its limits",fraser:"Assessed Fraser competence",emergency_contraception:"Offered emergency contraception",larc:"Explained LARC options",sti_test:"Offered STI testing",trusted_adult:"Encouraged a trusted adult",pregnancy_test:"Pregnancy test in 3 weeks"},
  bad:{insist_parents:"Insisted on telling mum",judgemental:"Judgemental",missed_ec:"Missed emergency contraception",jargon:"Jargon",vague_safety_net:"Vague safety-net"},
  clues:{condom_split:"Condom split 3 days ago",partner17:"Partner Jordan, 17",no_exploitation:"No pressure, gifts or substances",mum_phone:"Mum checks her phone",pregnancy_worry:"Worried she's pregnant",auntie:"Auntie is a trusted adult"},
  hints:{privacy_check:"Video call with a teenager: who's in the room?",partner_age:"How old is her partner?",last_upsi:"When did she last have sex without a condom?",emergency_contraception:"Is she within the window for emergency contraception?",confidentiality_limits:"What can you promise about confidentiality?",larc:"What's the most effective option?",sti_test:"STIs?"},
  hyp:"e.g. Fraser competent? Exploitation risk? Needs EC? UKMEC issues?",
  exam:`CASE: Video call with Mia, 15, requesting the pill without her mother knowing. Partner Jordan, 17, no exploitation features. Hidden: condom split 3 days ago (needs emergency contraception); worried she's pregnant; mum checks her phone.
WHAT EARNS MARKS:
Data gathering: privacy check; partner's age and nature of relationship; exploitation screen (pressure, gifts, substances, secrecy, school); last unprotected sex; UKMEC checks (migraine with aura, smoking, VTE history); support network.
Clinical management (weighted more): explains confidentiality and its limits; assesses Fraser competence; identifies need for emergency contraception now (copper IUD most effective within 5 days; levonorgestrel within 72 h or ulipristal within 120 h); pregnancy test in 3 weeks; ongoing contraception including LARC (implant); condoms and chlamydia/gonorrhoea testing; encourages a trusted adult without requiring it; safeguarding judgement (no referral needed here, but documents reasoning).
Relating to others: warm, non-judgemental, age-appropriate language; respects autonomy; checks understanding.
Common errors: missing emergency contraception; insisting on parental involvement; judgemental tone; promising absolute confidentiality; not asking the partner's age.`}},

/* ===================== 3. Faltering growth ===================== */
"u19-growth":{g:1,title:"Toddler not gaining weight",mode:"video",pt:"David",voice:"m",who:"David Okoro, father of Noah (14 months)",
 teach:{why:"Tests plotting and interpreting growth, a feeding history, sensible first investigations, and spotting social causes, including neglect, without accusation.",
  twist:"A previous clinician said 'he's just small'. Noah drinks over a litre of cow's milk a day, and money is tight since dad lost his job.",
  ice:["Ideas: 'He's just a fussy eater, like the doctor said.'","Concerns: something serious being missed; being judged as a bad parent.","Expectations: someone to take it seriously; maybe a test."],
  gather:["Growth: birth weight and centile, the trajectory (how many centile spaces crossed), length","Feeding: milk volume and type, meals, snacks, mealtime behaviour, juice","Stools: frequency, pale, bulky, offensive (malabsorption); vomiting","Symptoms of illness: recurrent infections, breathlessness on feeding, development","Social: who feeds him, money for food, housing, parental mood, support","Family heights; other children"],
  flags:["Weight falling below the 0.4th centile, or a very rapid fall","Signs of systemic illness, chronic diarrhoea, vomiting, developmental regression","Concern about neglect or safeguarding","Severe acute malnutrition signs"],
  manage:["Faltering growth (NICE NG75): fall across 1 or more centile spaces if birth weight was below the 9th centile; 2 or more if between the 9th and 91st; 3 or more if above the 91st; or currently below the 2nd centile","Measure length, plot weight and length, and repeat weights as agreed","Feeding assessment with the health visitor; food diary","Limit cow's milk to about 300–400 mL a day: large volumes fill toddlers up and cause iron deficiency","Tests guided by history: urine for UTI, coeliac serology (if eating gluten), FBC and ferritin","Refer to paediatrics if red flags, or failure to improve","Explore money and food worries; signpost Healthy Start and local support; consider safeguarding if neglect is suspected"],
  phrases:["'You were right to come back. Let's look at his chart together.'","'Lots of parents of toddlers find mealtimes a battle: tell me what a typical day looks like.'","'How much milk is he having a day, roughly?'","'Sometimes money gets tight and food is harder: is that something that's affecting you at the moment?'"],
  safety:"Return sooner if he becomes unwell, stops drinking, has persistent vomiting or diarrhoea, blood in the stool, or seems listless. Weight check with the health visitor in 2–4 weeks; results reviewed with dad.",
  pitfalls:{dg:["Not establishing the centile trajectory","Missing the milk volume","Not asking about stools","Avoiding the money question"],cm:["Reassuring without plotting growth","Over-investigating without a plan","No follow-up weight"],rto:["Repeating 'he's just small'","Accusatory safeguarding questions","Not acknowledging dad's frustration"]},
  src:"NICE NG75 Faltering growth (2017) · NICE CKS Iron deficiency anaemia · NHS Start for Life (milk for toddlers) · NICE NG20 Coeliac disease"},
 model:[["dr","Hello, I'm Dr Pinaware. Can I check who I'm speaking with, and Noah's date of birth? Is he with you?"],["pt","David Okoro, his dad. Noah's on my knee: tenth of September last year."],["dr","Hi Noah! Thanks, David. What's brought you in today?"],["pt","The health visitor weighed him and said he's dropped. We were told before he's just small, but I'm worried."],["dr","You were right to come back. Let's look at his chart. He was born around the 50th centile, and he's now nearer the 9th, so he's dropped across two lines. That's worth looking into properly. Can you tell me what a typical day of eating looks like?"],["pt","He's fussy with food. He mostly wants his bottle. Cow's milk, probably four or five bottles."],["dr","That's really helpful. Roughly how much is in each bottle?"],["pt","About 250 mils."],["dr","So over a litre a day. Milk is filling, so toddlers who drink that much often aren't hungry for food, and it can make them low in iron. How are his poos?"],["pt","Normal mostly. Sometimes loose."],["dr","Thank you. And how are things at home? Sometimes food gets harder when money's tight."],["pt","Honestly, I lost my job two months ago. We're managing. Just."],["dr","Thanks for telling me. That's a lot to carry, and it doesn't change how well you're looking after him. Here's what I suggest: cutting his milk down to about 300 to 400 mils a day, in a cup, and offering three meals and two snacks. I'd like a urine test and a blood test to check iron and for coeliac disease, and the health visitor to weigh him again in 3 weeks. How does that sound?"],["pt","OK. I didn't know the milk could do that."],["dr","Most people don't. I'll also give you information on Healthy Start vouchers and local support, if that's useful. If he becomes unwell, keeps vomiting, has blood in his poo or seems floppy, contact us the same day. Could you tell me the plan back?"],["pt","Less milk, in a cup, meals and snacks, a wee and blood test, weigh again in 3 weeks."]],
 live:{opening:"The health visitor said Noah's weight has dropped, and we were told before he's just small. I'm worried.",
  notes:[["Patient","Noah Okoro, 14 months"],["Consultation","Video call, father present with Noah"],["Birth","Term, 3.4 kg (50th centile)"],["Weights","9 months: 25th centile · 14 months: 9th centile (health visitor)"],["Immunisations","Up to date"],["Last contact","8 months: 'small but well', no follow-up"]],
  brief:`You are a trained SCA role-player. You play DAVID OKORO, 34, father of NOAH (14 months), on a VIDEO call with Noah on your knee. Calm but frustrated. Nigerian-British, plain British English, 1–3 sentences.
FACTS (when asked): Noah is "fussy"; mostly wants his bottle: cow's milk, 4–5 bottles of about 250 mL a day (over a litre). Eats a few spoons at meals, likes crisps. Stools sometimes loose, no blood, not pale or very smelly. No vomiting, no frequent infections, development normal (walking holding furniture, a few words). You and your wife are both average height. Your wife works nights at a warehouse; you do most feeding.
HIDDEN: You lost your job two months ago and money is tight; you sometimes skip meals yourself so the kids eat. Reveal ONLY if asked kindly about money, food or home. Concern: something serious being missed because you were brushed off before; also being judged a bad dad. Expectation: someone to take it seriously and do a test.
REACTIONS: If the doctor says "he's probably just small" again, become annoyed. If the doctor plots or explains the centile drop, feel listened to. If asked accusing questions ("Is he being fed enough?") become defensive. If milk advice is explained, you're surprised and willing. Accept tests and health visitor follow-up. Stay in character.`,
  dg:{growth_trajectory:"Growth trajectory and centiles",milk_volume:"Milk volume and type",meals:"Meals and snacks",stools_vomiting:"Stools and vomiting",illness_development:"Illness and development",social_money:"Money, food and home"},
  cm:{explain_centiles:"Explained the centile drop",milk_reduction:"Reduce milk to 300–400 mL, cup",meal_plan:"Meals and snacks plan",tests:"Urine, coeliac, FBC and ferritin",hv_followup:"Health visitor weight check",support_signpost:"Signposted support (Healthy Start)",paeds_threshold:"When to refer to paediatrics"},
  bad:{just_small:"Said 'just small' without assessing",accusing:"Accusing tone",jargon:"Jargon",vague_safety_net:"Vague safety-net"},
  clues:{milk_litre:"Over a litre of cow's milk a day",fussy:"Fussy with food",loose_stools:"Sometimes loose stools",job_loss:"Dad lost his job; money tight",brushed_off:"Brushed off before",dev_normal:"Development normal"},
  hints:{growth_trajectory:"How many centile lines has he crossed?",milk_volume:"How much milk does he drink?",stools_vomiting:"Stools?",social_money:"Is money or food a worry at home?",milk_reduction:"What should happen to the milk?",tests:"Which tests are sensible first?",hv_followup:"When will he be weighed again?"},
  hyp:"e.g. Excess milk and iron deficiency? Coeliac? Social causes? Neglect?",
  exam:`CASE: Video call with David, father of Noah (14 months). Weight fallen from 50th to 9th centile (two centile spaces). Hidden: drinks over a litre of cow's milk daily; occasional loose stools; dad lost his job and money is tight; previously told 'just small'.
WHAT EARNS MARKS:
Data gathering: growth trajectory; detailed feeding history including milk volume; stools; illness and development; sensitive social history including money and food; family heights.
Clinical management (weighted more): recognises faltering growth (NICE NG75); explains excess milk effect; reduce cow's milk to about 300–400 mL in a cup, meals and snacks; urine for UTI, coeliac serology, FBC/ferritin; health visitor follow-up weight in 2–4 weeks; paediatric referral if red flags or no improvement; signposts Healthy Start and support; considers safeguarding proportionately (no neglect here).
Relating to others: acknowledges frustration at being brushed off; non-judgemental about money; involves dad in the plan; plain language; teach-back.
Common errors: reassuring 'just small'; missing milk volume; accusatory questioning; no follow-up plan.`}},

/* ===================== 4. Eczema, steroid fear ===================== */
"u19-eczema":{g:1,title:"Eczema flaring: mum afraid of steroids",mode:"video",pt:"Fatima",voice:"f",who:"Fatima Hussain, mother of Zayn (4)",
 teach:{why:"A classic health-beliefs case: the marks are in exploring the fear, correcting it accurately, and agreeing a practical plan the parent will follow.",
  twist:"Mum stopped hydrocortisone after reading about 'steroid withdrawal' online and is using coconut oil. Zayn isn't sleeping.",
  ice:["Ideas: 'Steroids thin the skin and damage children.'","Concerns: harming him; also he's scratching until he bleeds and nobody's sleeping.","Expectations: a natural cream, or a referral to a skin specialist."],
  gather:["Extent, sites (face, flexures), itch, sleep, school impact","What's being used, how much, how often; soap and bath products","Signs of infection: weeping, crusting, pustules; rapidly worsening painful clustered blisters (eczema herpeticum)","Triggers: soaps, heat, wool, pets, foods (rarely), stress","Asthma, hay fever, food allergy","Her understanding of steroids and where it came from"],
  flags:["Eczema herpeticum (painful, punched-out erosions, unwell): same-day referral and aciclovir","Bacterial infection: weeping, crusting, fever","Severe eczema not responding to treatment; faltering growth; significant psychological impact"],
  manage:["Emollients: lots, often (250–500 g a week for a child), also as a soap substitute (NICE CG57)","Topical corticosteroid matched to severity: mild = hydrocortisone 1%; moderate = moderate potency (clobetasone butyrate 0.05%); severe = potent on the body (not the face). Face: mild, or moderate for 3–5 days in a severe flare","Once or twice daily for flares, usually 7–14 days, continuing until 48 hours after it settles; fingertip units guide the amount","Leave about 30 minutes between emollient and steroid","Frequent flares: 'weekend therapy' (steroid 2 days a week on usual sites) can be considered","Skin thinning is rare when the right strength is used correctly for short courses","Antihistamine at night only short-term if sleep is badly affected (sedating, over 6 months old)","Written eczema plan; review in 2–4 weeks"],
  phrases:["'What have you read about steroid creams? I'd like to understand your worries.'","'Used the right way, for short bursts, mild steroid creams are very safe. Eczema left untreated can damage the skin and his sleep much more.'","'Think of the steroid as a fire extinguisher for flares, and the moisturiser as daily fire prevention.'","'Shall we write down exactly how much and how long, so it's clear?'"],
  safety:"Same day if: the eczema suddenly gets painful with clusters of blisters or punched-out sores, he's unwell or feverish, or it's weeping and crusting. Review in 2–4 weeks; sooner if not improving after a week of treatment.",
  pitfalls:{dg:["Not exploring the steroid belief","Not asking about sleep and impact","Forgetting infection and herpeticum"],cm:["Just prescribing a stronger steroid","No quantity or duration","Not prescribing enough emollient"],rto:["Dismissing online information","Lecturing","Not checking she'll actually use the plan"]},
  src:"NICE CG57 Atopic eczema in under 12s (2007, updated 2023) · NICE CKS Eczema – atopic · NICE NG190 Secondary bacterial infection of eczema"},
 model:[["dr","Hello, I'm Dr Pinaware. Can I check who I'm speaking with and Zayn's date of birth?"],["pt","Fatima Hussain, I'm his mum. Zayn, twelfth of January 2022."],["dr","Thanks, Fatima. What's been happening with his skin?"],["pt","His eczema's really bad. He scratches till it bleeds and nobody's sleeping. I want something natural, or to see a specialist."],["dr","That sounds exhausting for all of you. What are you using at the moment?"],["pt","Coconut oil. We stopped the hydrocortisone, I read steroids thin the skin and cause withdrawal."],["dr","Thank you for telling me: lots of parents worry about that. Can you tell me more about what you read?"],["pt","There were pictures online of kids with red skin from stopping steroids."],["dr","I can see why that would frighten you. Those pictures are usually from strong creams used for long periods. Hydrocortisone 1% is the mildest steroid, and used for short bursts during flares it's very safe. Untreated eczema actually does more harm, to his skin and his sleep. Does that make sense?"],["pt","I suppose. I just don't want to hurt him."],["dr","Of course, and you're clearly a careful mum. Is the skin weeping, crusting, or are there clusters of painful blisters?"],["pt","No, just red and dry and scratched."],["dr","OK. Here's what I'd suggest: a proper moisturiser, lots of it, several times a day and instead of soap. Coconut oil can actually dry the skin. For the red patches, hydrocortisone once or twice a day for a week or two, until 2 days after it clears. I'll write down how much, using fingertip units. Would you be willing to try that?"],["pt","If it's written down, yes."],["dr","Great. If the skin suddenly becomes painful with blisters or he's unwell, call us the same day. Let's review in 2 weeks. Can you tell me the plan in your own words?"]],
 live:{opening:"His eczema's really bad. He scratches till it bleeds. I'd like something natural, or to see a skin specialist.",
  notes:[["Patient","Zayn Hussain, 4"],["Consultation","Video call with mum"],["Problems","Atopic eczema since 6 months; mild asthma"],["Repeats","Hydrocortisone 1% cream (last issued 5 months ago) · Emollient (not requested for 6 months)"],["Last seen","Nurse, 6 months ago: 'mild eczema, good control'"],["Allergies","None known"]],
  brief:`You are a trained SCA role-player. You play FATIMA HUSSAIN, 31, mother of ZAYN, 4, on a VIDEO call. Tired and worried, polite but firm. Plain British English, 1–3 sentences.
FACTS (when asked): Eczema worse for 6 weeks: inside elbows, behind knees, neck, a bit on cheeks; red, dry, scratched, sometimes bleeds; no weeping, crusting, blisters; he's well otherwise, no fever. Waking 3–4 times a night; nursery says he's tired and scratches. You stopped hydrocortisone 2 months ago and use coconut oil and a baby bubble bath. Mild asthma, OK.
HIDDEN: You read online about "topical steroid withdrawal" and saw pictures of children with red raw skin; you're scared of thinning his skin. Share fully only if the doctor asks what you've read or what worries you about steroids. Expectation: something natural, or a dermatology referral. You also feel guilty, as your mother-in-law says the eczema is your fault (share only if the doctor is warm and asks how you're coping).
REACTIONS: If the doctor just prescribes steroids without exploring, say "I'm not putting steroids on him." If the doctor explores and explains clearly (mild strength, short bursts, safety), become willing to try, especially with a written plan. If told off for stopping, become defensive. Accept emollient advice gladly. Stay in character.`,
  dg:{extent_sleep:"Extent, sleep and nursery impact",current_treatment:"Current treatments and soaps",steroid_belief:"Explored the steroid fear",infection_screen:"Infection and herpeticum screen",triggers:"Triggers",atopy:"Asthma and allergies",coping:"How mum is coping"},
  cm:{emollient_plan:"Emollient plan and soap substitute",steroid_explained:"Explained steroid safety accurately",steroid_plan:"Steroid strength, frequency, duration",written_plan:"Written plan or fingertip units",sleep_itch:"Addressed sleep and itch",review:"Review in 2–4 weeks",referral_criteria:"When referral would be needed"},
  bad:{dismissed_internet:"Dismissed what she read",lecture:"Lecturing or blaming",jargon:"Jargon",vague_safety_net:"Vague safety-net"},
  clues:{stopped_steroid:"Stopped hydrocortisone 2 months ago",coconut_oil:"Using coconut oil and bubble bath",tsw_fear:"Fear from 'steroid withdrawal' pictures",not_sleeping:"Waking 3–4 times a night",mil_blame:"Mother-in-law blames her",no_infection:"No weeping, crusting or blisters"},
  hints:{current_treatment:"What is she using now?",steroid_belief:"What has she read about steroids?",infection_screen:"Any signs of infection?",emollient_plan:"How much moisturiser, and soap?",steroid_plan:"Which strength, how often, how long?",written_plan:"Would writing it down help?"},
  hyp:"e.g. Undertreated eczema? Steroid phobia? Infection? Irritant soaps?",
  exam:`CASE: Video call with Fatima, mother of Zayn (4), eczema flare. Stopped hydrocortisone 2 months ago after reading about steroid withdrawal; using coconut oil and bubble bath; poor sleep. No infection. Hidden: guilt (mother-in-law blames her).
WHAT EARNS MARKS:
Data gathering: extent, sleep and impact; current products; explores steroid beliefs and source; infection and eczema herpeticum screen; triggers; atopy.
Clinical management (weighted more): generous emollient and soap substitute; accurate steroid explanation (mild potency, short courses, thinning rare when used correctly); clear steroid plan (once or twice daily, 7–14 days, until 48 h after settling; fingertip units); written eczema plan; sleep advice; review 2–4 weeks; same-day signs (herpeticum, infection); referral criteria.
Relating to others: validates her worry and research; non-blaming; supports her as a parent; shared decision; teach-back.
Common errors: prescribing without exploring; dismissing online information; no quantities or duration; lecturing about stopping steroids.`}},

/* ===================== 5. Teen self-harm ===================== */
"u19-selfharm":{g:1,title:"16-year-old self-harming: don't tell my parents",mode:"video",pt:"Ella",voice:"f",who:"Ella Morgan, 16",
 teach:{why:"Tests a sensitive psychosocial history, asking directly about suicide, confidentiality with a 16-year-old, and a collaborative safety plan with timely CAMHS involvement.",
  twist:"She's been cutting for 2 months after online bullying and her parents separating. She's scared of being 'sectioned' and of her parents finding out.",
  ice:["Ideas: 'It's just stress; I've got it under control.'","Concerns: being sent to hospital; her parents finding out.","Expectations: something to help her sleep; to keep it secret."],
  gather:["Open, then a psychosocial history: home, education, activities, drugs and alcohol, sexuality, suicide and self-harm, safety (HEADSSS)","Self-harm: method in general terms, frequency, last episode, wound care, any medical treatment needed","Suicidal thoughts directly: thoughts, plans, preparations, intent, past attempts","Mood, sleep, appetite, hopelessness; online bullying; substance use","Protective factors: people she trusts, reasons for living, school, future plans","Capacity at 16; who she'd be willing to involve"],
  flags:["Suicidal plan or intent, or recent attempt: same-day crisis assessment","Wounds needing medical care","Significant risk to her from others (abuse, exploitation)","Psychosis, severe depression, intoxication"],
  manage:["Don't use risk scales to predict suicide; assess needs and risk through a psychosocial conversation (NICE NG225)","Check wounds: clean, any that need closing or have signs of infection","Refer to CAMHS: urgency depends on risk (same day if high)","Agree a safety plan: warning signs, coping steps, people to contact, crisis numbers (Childline 0800 1111, Samaritans 116 123, Papyrus HOPELINE247, NHS 111 option 2 for mental health crisis in England)","Confidentiality: a 16-year-old is presumed to have capacity; share without consent only if there's a risk of serious harm, and tell her first","Encourage involving a parent or trusted adult, offer to help with that conversation","Follow-up within a week; school support with consent"],
  phrases:["'Many young people who feel like this tell no one, so thank you for telling me.'","'Sometimes when people feel this low they have thoughts of ending their life. Have you had thoughts like that?'","'I'm not going to send you to hospital for talking to me. I want to work out how to keep you safe together.'","'Who would you feel OK about knowing? Would it help if we told your mum together?'"],
  safety:"If she feels unable to keep herself safe: call 999 or go to A&E, or call NHS 111 option 2, Childline or Papyrus. Seek care for any wound that's deep, gaping or looks infected. Follow-up appointment within a week, booked before the end of the call.",
  pitfalls:{dg:["Not asking directly about suicide","Not asking about bullying, home or substances","No protective factors"],cm:["No safety plan","Promising complete secrecy, or telling parents without discussion","No follow-up date","Prescribing sleeping tablets"],rto:["Shock or judgement","Rushing","Talking about her rather than with her"]},
  src:"NICE NG225 Self-harm (2022) · NICE NG134 Depression in children and young people · GMC 0–18 years guidance · HEADSSS psychosocial assessment"},
 model:[["dr","Hi, I'm Dr Pinaware. Can I check your name and date of birth? And are you somewhere private?"],["pt","Ella Morgan, ninth of April 2010. Yeah, I'm in my room."],["dr","Thanks, Ella. What would you like to talk about today?"],["pt","I can't sleep. I just want something to help me sleep."],["dr","Not sleeping is horrible. What's been keeping you awake?"],["pt","Just stuff. School. Home. And… I've been hurting myself. Please don't tell my parents."],["dr","Thank you for telling me. That takes courage. I want you to know that what you tell me is private, unless I'm worried you're at serious risk of harm. If that happened, I'd talk to you first. Can you tell me more about the hurting?"],["pt","Cutting. My arm. For about two months. Not deep."],["dr","Are any of the cuts open, red, or needing a dressing?"],["pt","No. They're healing."],["dr","OK. Sometimes when people feel this low, they have thoughts of ending their life. Have you had thoughts like that?"],["pt","Sometimes I wish I just wasn't here. But I wouldn't do anything. I don't want to go to hospital."],["dr","I'm really glad you've told me. I'm not going to send you to hospital for talking to me. Have you made any plans, or anything you've got ready?"],["pt","No. Nothing like that."],["dr","What's been making things so hard?"],["pt","Some girls have been posting stuff about me. And my mum and dad are splitting up."],["dr","That's a lot to cope with at once. Who in your life do you feel close to?"],["pt","My mum, really. And my best friend, Leah."],["dr","Here's what I'd like to suggest: a referral to the young people's mental health team, who are good at exactly this, and together we'll write a plan for when the urge gets strong, with people and numbers you can call. I'd like to see you again on Friday. And would you think about telling your mum? I could help you do that."],["pt","Maybe… if you were there."]],
 live:{opening:"I can't sleep. I just want something to help me sleep.",
  notes:[["Patient","Ella Morgan, 16"],["Consultation","Video call, booked by the patient"],["Past history","Nil significant"],["Medicines","None"],["Last seen","Age 14, sports injury"],["Social","Lives with mum and dad; Year 11 (GCSEs)"]],
  brief:`You are a trained SCA role-player. You play ELLA MORGAN, 16, on a VIDEO call from your bedroom. Quiet, guarded, looks down; opens up slowly if the doctor is gentle and patient. Short answers.
FACTS (when asked, gently): Can't sleep for 2 months; mood low; dropping grades; stopped netball. You've been cutting your forearm with a pencil-sharpener blade for 2 months, a few times a week, last 2 days ago; cuts are superficial and healing; no medical treatment needed. Reveal the cutting only after the doctor asks openly about what's going on, or about how you've been coping, AND seems kind. Passive thoughts ("sometimes I wish I wasn't here"), no plans, no preparations, no previous attempts, you wouldn't act because of your mum and your dog. No alcohol or drugs, no one hurting you. Triggers: girls posting cruel things about you on social media; parents separating. Protective: mum, best friend Leah, your dog, want to study art.
HIDDEN: Terrified of being "sectioned" or put in hospital, and of your parents knowing. Expectation: sleeping tablets and secrecy.
REACTIONS: If the doctor is shocked, rushes, or says they must tell your parents immediately, shut down ("Forget it, I'm fine"). If they explain confidentiality and its limits kindly and reassure you about hospital, open up. Agree to CAMHS and a safety plan if explained. Willing to tell your mum if the doctor offers to help. Stay in character. Never describe methods in detail.`,
  dg:{headsss:"Psychosocial history (home, school, activities)",selfharm_details:"Self-harm details and wounds",suicide_direct:"Asked directly about suicide",plans_intent:"Plans, preparations, intent",triggers_bullying:"Triggers (bullying, home)",substances:"Drugs and alcohol",protective:"Protective factors"},
  cm:{confidentiality_limits:"Explained confidentiality and its limits",reassure_hospital:"Addressed fear of hospital",wound_check:"Checked wounds",camhs:"Referral to CAMHS",safety_plan:"Safety plan with crisis contacts",involve_parent:"Offered to help involve mum",follow_up_week:"Follow-up within a week",no_hypnotics:"Didn't simply prescribe sleeping tablets"},
  bad:{shock_judgement:"Shocked or judgemental",breach_without_discussion:"Planned to tell parents without discussion",rushing:"Rushed her",jargon:"Jargon",vague_safety_net:"Vague safety-net"},
  clues:{cutting:"Cutting forearm for 2 months",passive_si:"Passive thoughts, no plan",bullying:"Bullied online",parents_split:"Parents separating",protective_mum_leah:"Protective: mum, Leah, dog",fear_hospital:"Fears being sectioned"},
  hints:{headsss:"Explore home, school and activities.",selfharm_details:"How is she coping? Any self-harm?",suicide_direct:"Have you asked directly about suicidal thoughts?",protective:"What keeps her safe?",safety_plan:"What will she do if the urge gets strong?",involve_parent:"Could she involve someone she trusts?",follow_up_week:"When will you see her again?"},
  hyp:"e.g. Depression? Self-harm? Bullying? Risk level? Safeguarding?",
  exam:`CASE: Video call with Ella, 16, asking for sleeping tablets. Hidden: cutting forearm for 2 months (superficial, healing); passive death wishes, no plan or intent; online bullying; parents separating; fear of being sectioned and of parents knowing. Protective: mum, friend Leah, dog, art.
WHAT EARNS MARKS:
Data gathering: open approach; HEADSSS psychosocial history; self-harm details and wound check; asks directly about suicidal thoughts, plans, preparations and intent; triggers; substances; protective factors.
Clinical management (weighted more): proportionate risk judgement without scales (NICE NG225); explains confidentiality and its limits; reassures about hospital; CAMHS referral; collaborative safety plan with crisis numbers (Childline, Samaritans, Papyrus, 111 option 2); offers help involving mum; follow-up within a week; avoids hypnotics; school support with consent.
Relating to others: calm, warm, unhurried; thanks her for disclosure; respects autonomy at 16; checks understanding.
Common errors: not asking directly about suicide; no safety plan; telling parents without discussion or promising total secrecy; prescribing sleeping tablets; shock or judgement.`}},

/* ===================== 6. Constipation and soiling ===================== */
"u19-constipation":{g:1,title:"Soiling at school: 'he's just lazy'",mode:"phone",pt:"Sarah",voice:"f",who:"Sarah Taylor, mother of Alfie (5)",
 teach:{why:"Tests recognising chronic constipation with overflow, excluding red flags, starting disimpaction properly, and reframing blame, with sensitivity to family stress and safeguarding.",
  twist:"Mum thinks Alfie is soiling on purpose. A new baby arrived 3 months ago, and a teacher made a comment in front of the class.",
  ice:["Ideas: 'He's being lazy or naughty since the baby came.'","Concerns: he's being teased; something wrong inside.","Expectations: a laxative, or a referral."],
  gather:["Stool frequency, size, consistency (Bristol chart), pain, straining, withholding behaviour (crossing legs, hiding)","Soiling: frequency, loose or smeary (overflow)","Onset and triggers: potty training, diet change, illness, new sibling, school","Diet and fluids; toilet routine at school","Red flags: from birth or first weeks, delayed meconium, ribbon stools, leg weakness or abnormal walking, back abnormalities, abdominal distension with vomiting, faltering growth","Urine symptoms; emotional impact; safeguarding cues (only if concerns)"],
  flags:["Onset from birth or first few weeks of life; meconium after 48 hours","Ribbon stools, abdominal distension with vomiting","Leg weakness, abnormal gait or reflexes, sacral dimple or tuft","Faltering growth","Perianal bruising, fissures in unusual places or other concerns of abuse"],
  manage:["Diagnose chronic idiopathic constipation by history (NICE CG99); overflow soiling is involuntary","Disimpaction: macrogol (polyethylene glycol 3350 with electrolytes) on an escalating dose over 2 weeks until disimpaction; add a stimulant if not effective after 2 weeks","Then maintenance at about half the disimpaction dose, continuing for several weeks after a regular pattern, then reduce gradually over months","Toilet routine: sit for 5 minutes after meals, footstool, rewards for sitting (not for clean pants)","Fluids and fibre, but not diet alone as first-line","Tell the school: easy toilet access; school nurse","Review in 2 weeks; refer if red flags or not responding"],
  phrases:["'When poo gets stuck, the bowel stretches and loose poo leaks around it. He can't feel it or stop it: it's not naughtiness.'","'How has he been since the new baby arrived?'","'Let's praise him for sitting on the toilet, not for clean pants, so he doesn't feel punished.'","'The medicine dose goes up over a few days, and it may get messier before it gets better.'"],
  safety:"Seek help the same day for: tummy swelling with vomiting, severe pain, blood in the poo beyond a streak, or weakness in his legs. Expect some extra leakage during disimpaction. Review in 2 weeks.",
  pitfalls:{dg:["Not asking about withholding","Missing red flags (legs, onset from birth)","Not asking about the new baby or school"],cm:["Too-low or stop-start laxative dosing","Diet advice alone","No maintenance plan"],rto:["Agreeing he's lazy","Blaming mum","Not involving Alfie's feelings"]},
  src:"NICE CG99 Constipation in children and young people (2010, updated 2017) · NICE CKS Constipation in children · ERIC, the Children's Bowel and Bladder Charity"},
 model:[["dr","Hello, it's Dr Pinaware. Am I speaking to Alfie's mum? Can I check his date of birth?"],["pt","Yes, Sarah. Alfie's eighth of July 2021."],["dr","Thanks, Sarah. What's been happening?"],["pt","He keeps pooing his pants at school. I think he's just being lazy since the baby came."],["dr","That sounds really stressful. Can I ask about his poos: how often does he go, and what are they like?"],["pt","Maybe twice a week. Big, hard ones, and they hurt. Then the pants are smeary."],["dr","Does he ever cross his legs, hide, or seem to hold on?"],["pt","Yes! He goes behind the sofa and stands on tiptoes."],["dr","That's really helpful. That's holding on. It sounds like Alfie is constipated, and the smearing is liquid poo leaking around a hard lump. He can't feel it or control it, so it isn't laziness."],["pt","Oh. I've been telling him off."],["dr","Most parents would think the same, and you couldn't have known. Has this been going on since he was a baby, or did it start more recently?"],["pt","Since about when the baby came. Three months."],["dr","And has he had any weakness in his legs, a swollen tummy with vomiting, or problems from birth?"],["pt","No, nothing like that."],["dr","Good. The plan is a medicine called macrogol, a powder in a drink. The dose goes up over a few days to clear the blockage, and it may get messier first. Then a smaller daily dose for a few months. Sitting on the toilet for 5 minutes after meals, with a footstool, and lots of praise for sitting, not for clean pants. And I can write to school so he can use the toilet easily."],["pt","That would help. A teacher said something in front of his class."],["dr","I'm sorry he went through that. A letter will help. If his tummy swells and he vomits, or his legs seem weak, contact us the same day. Let's speak again in 2 weeks. Could you tell me back how the medicine works?"]],
 live:{opening:"He keeps pooing his pants at school. I think he's just being lazy since the new baby came.",
  notes:[["Patient","Alfie Taylor, 5"],["Caller","Sarah Taylor (mother)"],["Consultation","Telephone"],["Past history","Born at term; normal development"],["Medicines","None"],["Social","New sibling (3 months); Reception class"]],
  brief:`You are a trained SCA role-player. You play SARAH TAYLOR, 32, mother of ALFIE, 5, on a PHONE call. Tired (3-month-old baby), a bit exasperated, but loves Alfie. Plain British English, 1–3 sentences.
FACTS (when asked): For 3 months Alfie poos about twice a week: large, hard, painful; smeary loose soiling in his pants most days. He hides behind the sofa, crosses his legs and stands on tiptoes (withholding). Eats beige food, drinks squash, not much water. No blood except a streak once. Started around the time the baby was born. No problems as a baby, meconium normal, no leg weakness, walks and runs normally, no tummy swelling or vomiting, growing fine, wees normally.
HIDDEN: You've been telling him off, thinking it's naughtiness. A teacher said "Alfie's had another accident" in front of the class, and he cried. Reveal the teacher if the doctor asks about school or how Alfie feels. Concern: he's being teased; also "is something blocked inside?" Expectation: some medicine or a referral.
REACTIONS: If the doctor explains overflow soiling clearly, you're relieved and a bit guilty. If the doctor implies you're to blame, become defensive. Accept macrogol and the toilet routine if explained. Want a letter for school. Stay in character.`,
  dg:{stool_pattern:"Stool frequency, size, pain",withholding:"Withholding behaviour",soiling:"Soiling pattern",onset_triggers:"Onset and triggers (new baby)",red_flags:"Red flags (birth, legs, distension)",diet_fluids:"Diet and fluids",school_feelings:"School and Alfie's feelings"},
  cm:{explain_overflow:"Explained overflow soiling",macrogol_disimpaction:"Macrogol disimpaction, escalating",maintenance:"Maintenance and gradual weaning",toilet_routine:"Toilet routine and rewards for sitting",school_letter:"Letter or plan for school",review_2wk:"Review in 2 weeks"},
  bad:{agree_lazy:"Agreed it's naughtiness",blame:"Blamed the parent",diet_only:"Diet advice alone",jargon:"Jargon",vague_safety_net:"Vague safety-net"},
  clues:{twice_week:"Hard painful stools twice a week",withholding:"Hides, crosses legs, tiptoes",smearing:"Smeary soiling most days",new_baby:"Started with the new baby",teacher:"Teacher embarrassed him in class",no_red_flags:"No red flags"},
  hints:{stool_pattern:"How often and what are the stools like?",withholding:"Any holding-on behaviour?",red_flags:"Have you excluded red flags?",explain_overflow:"Why is he soiling?",macrogol_disimpaction:"How do you clear the blockage?",toilet_routine:"Routine and rewards?",school_letter:"What about school?"},
  hyp:"e.g. Chronic constipation with overflow? Red flags? Emotional triggers?",
  exam:`CASE: Phone call with Sarah, mother of Alfie (5), soiling at school. Chronic constipation with overflow and withholding, starting with new sibling 3 months ago. No red flags. Hidden: mum has been telling him off; a teacher embarrassed him in class.
WHAT EARNS MARKS:
Data gathering: stool pattern and pain; withholding; soiling; onset and triggers; red flags (from birth, meconium, legs, distension and vomiting, growth); diet and fluids; school and emotions.
Clinical management (weighted more): diagnosis of constipation with overflow explained in plain words; macrogol disimpaction with escalating dose (warning it may get messier), maintenance for weeks to months with gradual reduction; toilet routine after meals, footstool, rewards for sitting; school letter; review in 2 weeks; red-flag safety-net.
Relating to others: reframes blame without judging mum; empathy about new baby and teacher; involves Alfie's feelings; checks understanding.
Common errors: agreeing it's behavioural; diet advice alone; low or stop-start laxative dosing; missing red flags; blaming the parent.`}},

/* ===================== 7. ADHD request ===================== */
"u19-adhd":{g:1,title:"School says ADHD: mum wants medication",mode:"video",pt:"Kerry",voice:"f",who:"Kerry Walsh, mother of Kai (8)",
 teach:{why:"Tests knowing the GP's role (not to diagnose or start ADHD medication), gathering evidence across settings, considering other explanations, and managing frustration with realistic waits.",
  twist:"Mum wants medication now because Kai is at risk of exclusion. Dad has similar traits. Mum is exhausted and feels judged.",
  ice:["Ideas: 'He's got ADHD: the school says so.'","Concerns: exclusion from school; being seen as a bad parent.","Expectations: a referral today, and medication."],
  gather:["Symptoms: inattention, hyperactivity, impulsivity; since when; in which settings (home, school, clubs)","Impact: learning, friendships, safety, family life","School view: SENCO involvement, written reports, support in place","Other explanations: hearing or vision problems, learning difficulty, anxiety, trauma or adversity, sleep problems including snoring (sleep apnoea), autism features","Development, family history (neurodevelopmental conditions), home stressors","Parent's wellbeing and support"],
  flags:["Risk to safety (running into roads, self-harm)","Safeguarding concerns or significant adversity at home","Severe impairment or exclusion: faster referral"],
  manage:["GP doesn't diagnose ADHD or start medication; diagnosis is by a specialist (paediatrics or CAMHS) (NICE NG87)","If behaviour suggests ADHD: watchful waiting up to 10 weeks or a parent support programme; refer for specialist assessment if symptoms persist with at least moderate impairment","Ask school (with consent) for a report and SENCO involvement; support doesn't need a diagnosis","Parent training or support groups don't need a diagnosis","Treat or check other causes: hearing, vision, sleep","Be honest about waiting times; give interim strategies and support for mum"],
  phrases:["'I can hear how hard this has been for you, and for Kai.'","'It's not something a GP can diagnose or start medicine for: that's done by a specialist, but I can get that process moving.'","'Is he like this everywhere, or mainly at school?'","'Support at school doesn't have to wait for a diagnosis.'"],
  safety:"Contact us sooner if Kai's safety is at risk, if there's a school exclusion, or if mum feels she can't cope. Review in 6–10 weeks with the school's report; chase referral if no letter in 8 weeks.",
  pitfalls:{dg:["Not asking about home vs school","Missing sleep, hearing and learning problems","Not asking how mum is"],cm:["Promising or prescribing medication","Diagnosing ADHD","No interim support or school liaison"],rto:["Dismissing the school's concerns","Implying it's parenting","Over-promising waiting times"]},
  src:"NICE NG87 Attention deficit hyperactivity disorder (2018, updated 2019) · NICE CKS ADHD · SEND Code of Practice (2015)"},
 model:[["dr","Hello, I'm Dr Pinaware. Can I check who I'm speaking with, and Kai's date of birth?"],["pt","Kerry Walsh, Kai's mum. He's 8, third of March 2018."],["dr","Thanks, Kerry. What's brought you in?"],["pt","The school says he's got ADHD. He can't sit still and he's been sent out of class again. I want him on medication."],["dr","That sounds really hard for both of you. Can you tell me what Kai's like at home?"],["pt","Same. Never stops. Can't finish anything. Climbs everything. It's been like that since he was little."],["dr","That's helpful: so it's at home and school, for years. How's he sleeping? Does he snore?"],["pt","He's up late, but no, he doesn't snore."],["dr","Any concerns about his hearing or eyesight, or with reading and learning?"],["pt","His hearing's fine. Reading's behind. His dad was the same as a kid, and he's dyslexic."],["dr","Thanks. And how are you managing?"],["pt","Honestly, I'm exhausted. People look at me like I'm a bad mum."],["dr","You're clearly not: you're here fighting for him. I'll be honest about how this works: ADHD has to be diagnosed by a specialist, and they're the ones who'd decide about medicine. A GP can't start it. What I can do is refer Kai to the paediatric team today, and ask school for a report from his teacher and the SENCO to go with it."],["pt","How long will that take?"],["dr","Waits are long here, often many months, and I don't want to pretend otherwise. In the meantime, there's a parent support programme I can refer you to, and school can put support in place now without a diagnosis. Would those help?"],["pt","Yes. Anything."],["dr","If he's ever at risk of hurting himself, or if he's excluded, contact us and I'll update the referral. Let's review in about 8 weeks. Can you tell me what we've agreed?"]],
 live:{opening:"The school says Kai's got ADHD. He's been sent out of class again. I want him on medication.",
  notes:[["Patient","Kai Walsh, 8"],["Consultation","Video call with mum"],["Past history","Glue ear age 3 (resolved); hearing test normal age 5"],["Medicines","None"],["Letter","School note: 'Concerns re attention and behaviour; parent advised to see GP'"],["Social","Lives with mum and younger sister; dad lives nearby"]],
  brief:`You are a trained SCA role-player. You play KERRY WALSH, 35, mother of KAI, 8, on a VIDEO call. Frustrated, determined, tired. Plain British English, 1–3 sentences.
FACTS (when asked): Since toddlerhood Kai can't sit still, interrupts, climbs everything, loses things, doesn't finish tasks, impulsive (once ran into the road after a ball). Same at home, school and football club. Reading behind; school has a SENCO but nothing formal yet. Sleeps late (11pm) but doesn't snore; hearing tested normal at 5; eyesight fine. Kai's dad was "the same as a kid" and is dyslexic. No trauma, no one hurting him. Kai is sometimes sad that he "gets into trouble".
HIDDEN: You're exhausted, your own GP said you might be depressed last year, and people judge you as a bad mum. Reveal if asked how you are coping. You fear Kai will be excluded (school mentioned a fixed-term exclusion). Expectation: medication now; you read Ritalin works quickly.
REACTIONS: If the doctor dismisses the school or implies parenting, get angry. If told the GP can't prescribe, be disappointed but accept if explained kindly with a clear plan. If offered a parent programme alone, say "So it's my fault?" unless it's framed as support. Ask about waiting times. Stay in character.`,
  dg:{symptoms_settings:"Symptoms across settings and duration",impact:"Impact on learning, safety, family",school_info:"School view and SENCO",other_causes:"Sleep, hearing, vision, learning",family_history:"Family history",parent_wellbeing:"Mum's wellbeing"},
  cm:{gp_role:"Explained GP can't diagnose or start medication",refer_specialist:"Referral for specialist assessment",school_report:"School report and SENCO",parent_programme:"Parent support programme (framed as support)",interim_support:"Interim school support without diagnosis",honest_wait:"Honest about waiting times",mum_support:"Support for mum's wellbeing"},
  bad:{promised_meds:"Promised or prescribed medication",blamed_parenting:"Implied poor parenting",dismissed_school:"Dismissed the concerns",jargon:"Jargon",vague_safety_net:"Vague safety-net"},
  clues:{all_settings:"Symptoms at home, school and football",early_onset:"Since toddlerhood",road_incident:"Ran into the road",dad_similar:"Dad similar, dyslexic",exclusion_risk:"Risk of exclusion",mum_exhausted:"Mum exhausted, feels judged"},
  hints:{symptoms_settings:"Is it in more than one setting?",other_causes:"Have you checked sleep, hearing, vision and learning?",parent_wellbeing:"How is mum coping?",gp_role:"Who diagnoses and prescribes?",school_report:"What information do specialists need?",honest_wait:"What about the wait?"},
  hyp:"e.g. ADHD? Specific learning difficulty? Sleep? Family stress?",
  exam:`CASE: Video call with Kerry, mother of Kai (8), school suggests ADHD; mum wants medication. Pervasive symptoms since toddlerhood across settings; reading behind; dad similar and dyslexic. Hidden: exclusion risk; mum exhausted and feels judged.
WHAT EARNS MARKS:
Data gathering: symptoms across settings and duration; impact and safety; school's view and SENCO; other causes (sleep/snoring, hearing, vision, learning difficulty, anxiety, adversity); family history; mum's wellbeing.
Clinical management (weighted more): GP doesn't diagnose or initiate ADHD medication (NICE NG87); referral for specialist assessment given moderate impairment; requests school report; parent support programme framed as support; school support without diagnosis; honest about waits; supports mum; safety-net and review.
Relating to others: validates frustration; non-blaming; manages expectations honestly but kindly; shared plan; teach-back.
Common errors: promising medication; diagnosing ADHD; implying poor parenting; ignoring mum's wellbeing; unrealistic wait promises.`}},

/* ===================== 8. Bruising in a non-mobile baby ===================== */
"u19-bruise":{g:1,title:"Bruise on a 5-month-old baby",mode:"video",pt:"Jade",voice:"f",who:"Jade Price, mother of Isla (5 months)",
 teach:{why:"Tests recognising a sentinel injury, acting on safeguarding procedures the same day, and being honest and supportive with a parent without accusing anyone.",
  twist:"Mum booked about a cough. She mentions a bruise on Isla's ear, explained as 'rolling into the cot bars'. Her new partner looks after Isla in the evenings.",
  ice:["Ideas: 'She must have knocked it on the cot.'","Concerns: social services taking her baby.","Expectations: cough medicine; a quick reassurance about the bruise."],
  gather:["Deal with the presenting complaint briefly and safely (the cough)","The bruise: where, size, colour, when noticed, the explanation and whether it fits Isla's development","Mobility: rolling? sitting? Not independently mobile at 5 months","Other injuries, bruises, bleeding, vomiting, irritability, drowsiness (head injury)","Who cares for Isla; household; support; stress","Previous concerns, A&E visits, health visitor contact"],
  flags:["Any bruise in a baby who isn't independently mobile ('those who don't cruise rarely bruise')","Bruises on the ears, neck, torso, face, or patterned bruises (TEN-4-FACESp)","Explanation that doesn't fit the injury or development","Signs of head injury: drowsy, vomiting, irritable, bulging fontanelle"],
  manage:["Suspect maltreatment for bruising in a non-mobile child (NICE CG89)","Same-day paediatric assessment for a child protection medical; refer to children's social care following local procedures","Discuss with the practice safeguarding lead; document exactly what was said and seen","Explain honestly to the parent that this is standard procedure for any bruise at this age, without accusing anyone","Don't investigate or decide who caused it yourself; don't delay","If the parent refuses, or the baby is at immediate risk: contact children's social care or police (999)","Plan who brings Isla, when, and where; check her safety in the meantime"],
  phrases:["'Thank you for mentioning the bruise. I'm really glad you did.'","'When a baby who can't move around yet has a bruise, we always ask a children's doctor to check them the same day. We do this for every baby, so nothing is missed.'","'This isn't me saying anyone has done anything wrong.'","'Part of the process is that children's social care are told. Their job is to support families and keep babies safe.'"],
  safety:"Go straight to A&E or call 999 if Isla becomes drowsy, floppy, vomits repeatedly, has a fit, or has trouble breathing. The paediatric appointment today is essential: if anything stops you getting there, phone the practice straight away.",
  pitfalls:{dg:["Not asking about mobility","Accepting the explanation","Not asking who looks after Isla"],cm:["Reassuring and treating the cough only","Arranging a routine appointment instead of same day","Not informing safeguarding or social care"],rto:["Accusing mum or her partner","Hiding the referral from mum","Lack of support for mum"]},
  src:"NICE CG89 Child maltreatment: when to suspect (2009, updated 2017) · RCPCH Child Protection Evidence: bruising · Working Together to Safeguard Children (2023) · TEN-4-FACESp bruising rule"},
 model:[["dr","Hello, I'm Dr Pinaware. Can I check who I'm speaking with, and Isla's date of birth?"],["pt","Jade Price, her mum. Isla, fourteenth of June."],["dr","Thanks, Jade. You've booked about a cough. Tell me about it."],["pt","She's had a snuffly cough for three days. She's feeding OK, no temperature."],["dr","Any fast breathing, sucking in under the ribs, or fewer wet nappies?"],["pt","No, she's fine in herself. Oh, and she's got a bruise on her ear. She rolled into the cot bars, I think."],["dr","Thank you for mentioning it. I'm glad you did. Could you show me on the camera?"],["pt","Here. It's on the back of her left ear."],["dr","I can see it. Can Isla roll over or sit up yet?"],["pt","Not really. She's started trying to roll."],["dr","Who looks after Isla during the day and evening?"],["pt","Me, and my partner Liam when I'm at work in the evenings."],["dr","Thank you. Jade, when a baby who can't move about on their own yet has a bruise, we always ask a children's doctor to check them the same day. We do this for every baby, so nothing is missed. It's not me saying anyone has done anything wrong."],["pt","Are you saying someone hurt her? Will they take her off me?"],["dr","I'm not saying that, and I can see how frightening this is. Part of the process is that children's social care are told: their job is to support families and make sure babies are safe. I'd like you to take Isla to the children's unit this afternoon. I'll ring them now so they're expecting you. Can you get there by 3?"],["pt","Yes. My mum can drive me."],["dr","Good. If she becomes drowsy, floppy, vomits again and again, or has a fit, call 999. Her cough sounds like a cold: keep her feeds going. Can you tell me back the plan?"]],
 live:{opening:"Hiya, it's about Isla's cough. She's been snuffly for three days.",
  notes:[["Patient","Isla Price, 5 months"],["Consultation","Video call, booked as 'baby cough'"],["Birth","Term, normal delivery"],["Immunisations","Up to date"],["Health visitor","2 weeks ago: 'feeding well, developing normally'"],["Social","Lives with mum (Jade, 22) and mum's partner"]],
  brief:`You are a trained SCA role-player. You play JADE PRICE, 22, mother of ISLA, 5 months, on a VIDEO call with Isla in your arms. Young, chatty, a bit anxious; loves Isla. Plain British English, 1–3 sentences.
FACTS (when asked): Snuffly cough 3 days, no fever, feeding normally (bottle), plenty of wet nappies, no fast breathing or ribs sucking in, no vomiting, alert and smiley. Near the end, or if the doctor asks if there's anything else, mention: "Oh, and she's got a bruise on her ear. She rolled into the cot bars, I think." If asked to show it: a bluish bruise behind the left ear, noticed this morning. Isla can't roll over fully or sit yet. Your partner Liam (not Isla's dad, together 4 months) looks after Isla when you work evening shifts at a bar; you noticed the bruise the morning after his shift. No other bruises you've noticed; no drowsiness or vomiting. Health visitor last saw her 2 weeks ago.
HIDDEN: You're worried too, Liam gets stressed when Isla cries, but you're scared that if you say so, social services will take her. Reveal Liam's stress only if the doctor is calm, kind, and non-accusing, and asks about support or how things are at home. Concern: losing Isla. Expectation: cough advice and reassurance.
REACTIONS: If the doctor accuses you or Liam, become upset and defensive ("I didn't do anything!"). If the doctor explains it's standard for every baby and supportive, become tearful but cooperative and agree to go today (your mum can drive you). If the doctor just reassures about the bruise, accept relieved. Stay in character.`,
  dg:{cough_assessment:"Assessed the cough safely",bruise_details:"Bruise site, when noticed, explanation",mobility:"Asked about Isla's mobility",other_injuries:"Other injuries, head-injury signs",carers_household:"Who looks after Isla; household",home_support:"Support and stress at home"},
  cm:{recognised_concern:"Recognised bruising in a non-mobile baby",same_day_paeds:"Same-day paediatric assessment",social_care:"Explained children's social care involvement",safeguarding_lead:"Inform safeguarding lead; document",honest_non_accusing:"Honest and non-accusing explanation",practical_plan:"Practical plan: who, when, where",cough_advice:"Cough advice"},
  bad:{reassured_bruise:"Accepted the explanation and reassured",accusing:"Accusing tone",hid_referral:"Hid the referral from mum",jargon:"Jargon",vague_safety_net:"Vague safety-net"},
  clues:{ear_bruise:"Bruise behind left ear",not_mobile:"Can't roll or sit yet",liam_evenings:"Partner Liam cares in evenings",after_shift:"Noticed after Liam's shift",liam_stressed:"Liam gets stressed when she cries",fear_removal:"Fears Isla being taken away",cough_viral:"Cough: well, feeding, no fever"},
  hints:{cough_assessment:"Deal with the cough safely first.",bruise_details:"Where's the bruise, and what's the explanation?",mobility:"Is Isla independently mobile?",carers_household:"Who looks after her?",same_day_paeds:"How urgent is this?",social_care:"What will you tell mum about the process?",honest_non_accusing:"How can you be honest without accusing?"},
  hyp:"e.g. Viral cough? Bruise in a non-mobile infant: non-accidental injury?",
  exam:`CASE: Video call with Jade, mother of Isla (5 months), booked for a cough (viral, well). Mentions a bruise behind Isla's left ear 'from cot bars'. Isla isn't independently mobile. Partner Liam (not the father) cares for her on evenings; bruise noticed after his shift; he gets stressed when she cries. Mum fears social services removing Isla.
WHAT EARNS MARKS:
Data gathering: safe cough assessment; bruise details and explanation; developmental mobility; other injuries and head-injury signs; carers and household; supportive enquiry about home.
Clinical management (weighted more): recognises bruising in a non-mobile infant as a safeguarding concern (NICE CG89); same-day paediatric assessment arranged directly; children's social care referral per local procedures; informs safeguarding lead and documents; explains honestly and without accusation; practical plan for getting there; escalation if refused; cough advice; red-flag safety-net.
Relating to others: calm, supportive, transparent; acknowledges fear; avoids blame; checks understanding.
Common errors: accepting the explanation; routine rather than same-day action; accusing the parent or partner; not telling mum about the referral.`}}
};

/* which SCA week a date falls in: clinic and practice weeks alternate, 2 weeks per group, 24-week cycle */
function scaWeek(d){d=d?new Date(d):new Date();const s=new Date(SCA_CYCLE.start+"T00:00:00"),D=864e5;let i=Math.floor((d-s)/(7*D));const pre=i<0;if(pre)i=0;
 const n=SCA_CYCLE.order.length,gi=Math.floor(i/2)%n,g=SCA_CYCLE.order[gi],ws=new Date(s.getTime()+i*7*D);
 return {i,pre,group:g,phase:i%2===0?"clinic":"practice",cycle:Math.floor(i/(2*n))+1,start:ws,end:new Date(ws.getTime()+6*D),
  practiced:SCA_CYCLE.order.slice(0,gi+(i%2)).filter(x=>x!==g)}}
const scaCasesIn=g=>Object.entries(SCA_CASES).filter(([k,c])=>c.g===g).map(([k,c])=>({id:k,...c}));
